create or replace function private.enforce_private_vote_identity() returns trigger language plpgsql security definer set search_path='' as $$ declare method text; ok boolean; begin select verification_method into method from public.events where id=new.event_id; if method='invite_code' then select exists(select 1 from public.event_access_code_redemptions r join public.event_access_codes c on c.id=r.access_code_id where c.event_id=new.event_id and r.voter_user_id=new.voter_user_id and (c.expires_at is null or c.expires_at>now())) into ok; if not ok then raise exception 'Redeem an event access code before voting' using errcode='42501'; end if; elsif method='voter_list' then select exists(select 1 from public.event_voter_list_entries l where l.event_id=new.event_id and l.redeemed_by=new.voter_user_id and l.used_votes+new.quantity<=l.max_votes) into ok; if not ok then raise exception 'Verify your approved voter-list identity before voting' using errcode='42501'; end if; update public.event_voter_list_entries set used_votes=used_votes+new.quantity where event_id=new.event_id and redeemed_by=new.voter_user_id; end if; return new; end $$;
drop trigger if exists enforce_voter_list_vote on public.vote_batches;
drop trigger if exists enforce_private_vote_identity on public.vote_batches;
create trigger enforce_private_vote_identity before insert on public.vote_batches for each row execute function private.enforce_private_vote_identity();
